import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.DhF4LrUq.js";const u=JSON.parse('{"title":"Roll back a release","description":"Roll back a release - the ROLLED_BACK crossing, the staged-rollout rollback, and halting the store curves, with the mandatory reason everywhere.","frontmatter":{"description":"Roll back a release - the ROLLED_BACK crossing, the staged-rollout rollback, and halting the store curves, with the mandatory reason everywhere."},"headers":[],"relativePath":"how-to/console/rollback.md","filePath":"how-to/console/rollback.md"}'),r={name:"how-to/console/rollback.md"};function l(n,e,i,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="roll-back-a-release" tabindex="-1">Roll back a release <a class="header-anchor" href="#roll-back-a-release" aria-label="Permalink to &quot;Roll back a release&quot;">​</a></h1><p>ShipperDog offers three rollback moves, one per axis. Pick the one that matches what went wrong; all of them demand a reason, and none of them erases the record.</p><table tabindex="0"><thead><tr><th>What happened</th><th>The move</th><th>Where</th></tr></thead><tbody><tr><td>The release itself is bad — pull it entirely</td><td>The <code>ROLLED_BACK</code> crossing</td><td>Release dashboard, Lifecycle block</td></tr><tr><td>A staged production rollout must stop widening</td><td>The staged-rollout rollback</td><td>Release dashboard, staged block</td></tr><tr><td>Only the store-side curve must pause or stop</td><td>Pause / Halt the curve</td><td>Release dashboard, curve block</td></tr></tbody></table><h2 id="pull-the-release-rolled-back" tabindex="-1">Pull the release: ROLLED_BACK <a class="header-anchor" href="#pull-the-release-rolled-back" aria-label="Permalink to &quot;Pull the release: ROLLED_BACK&quot;">​</a></h2><ol><li><p>Open the release (Releases — View). The <strong>Lifecycle</strong> block offers the state machine&#39;s legal edges — on an ACTIVE release, <strong>Rolled back</strong> is one of them.</p></li><li><p>Click it. The dialog requires a <strong>reason</strong> — a rolled-back release explains itself, and the reason rides the state timeline permanently.</p></li><li><p>Confirm. Downloads cut at the moment of the crossing: a tester outside the window gets the same &quot;no version available&quot; answer as one never granted — never a stale binary, and the <a href="/shipperdog/snapshot/how-to/portal/browse-apps">portal</a> simply stops offering the build.</p></li></ol><p><code>ROLLED_BACK</code> is terminal: the release stays readable with its full history, but it never dispatches again. The same move exists as a CLI verb for pipelines: <code>shipperdog release transition R-1028 ROLLED_BACK --reason &quot;crash spike on Android 14&quot;</code>.</p><div class="tip custom-block"><p class="custom-block-title">Failed versus rolled back</p><p><strong>Failed</strong> is the other terminal exit — for a release that never became healthy (validation, deployment). Both demand a reason; both keep the audit trail. Choose rolled back for &quot;was good, must come out&quot;; failed for &quot;never was good&quot;.</p></div><h2 id="stop-a-staged-rollout" tabindex="-1">Stop a staged rollout <a class="header-anchor" href="#stop-a-staged-rollout" aria-label="Permalink to &quot;Stop a staged rollout&quot;">​</a></h2><p>If the release is mid-<a href="/shipperdog/snapshot/how-to/console/staged-rollout">staged rollout</a>, the staged block&#39;s <strong>Roll back</strong> button is the one action that stops everything: reached TestFlight groups emptied, the Play user-fraction halted, Apple&#39;s phased curve halted, platform availability cut — with your mandatory reason on the timeline.</p><h2 id="halt-only-the-store-curve" tabindex="-1">Halt only the store curve <a class="header-anchor" href="#halt-only-the-store-curve" aria-label="Permalink to &quot;Halt only the store curve&quot;">​</a></h2><p>When the release itself is fine but the store-side curve must stop:</p><ul><li><strong>App Store phased release</strong> — <strong>Halt (release to all)</strong> completes Apple&#39;s 7-day availability curve immediately: every remaining user gets the update at once (Apple offers no binary rollback — the button says what it does). <strong>Pause</strong> / <strong>Resume</strong> freeze and continue the day-based widening.</li><li><strong>Staged rollout (Google Play)</strong> — <strong>Halt</strong> stops the user-fraction widening where it stands; <strong>Resume</strong> continues it; <strong>Re-apply intent</strong> re-drives the store to the intended fraction after drift.</li></ul><h2 id="what-stays-behind" tabindex="-1">What stays behind <a class="header-anchor" href="#what-stays-behind" aria-label="Permalink to &quot;What stays behind&quot;">​</a></h2><p>Everything: the state timeline&#39;s crossing with actor and reason, the promotion timeline&#39;s record, the frozen manifest of what had shipped, and every audit event. Compliance reads it all through the <a href="/shipperdog/snapshot/how-to/console/siem-streams">SIEM stream</a>. A bad release is a fact; rollback makes it a well-documented one.</p><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/staged-rollout">staged rollout</a> · <a href="/shipperdog/snapshot/how-to/console/releases">work with releases</a> · <a href="/shipperdog/snapshot/concepts/release-lifecycle">release lifecycle concepts</a></p>',15)])])}const g=t(r,[["render",l]]);export{u as __pageData,g as default};
